const tests = [
  { prompt: 'Extract cities: Paris, Rome', expect: ['Paris','Rome'] },
  { prompt: 'Extract cities: Madrid', expect: ['Madrid'] }
];
let tp=0, fp=0, fn=0;
for (const t of tests) {
  const out = await llm.extractCities(t.prompt); // returns array
  const setO = new Set(out), setE = new Set(t.expect);
  for (const x of setO) (setE.has(x) ? tp++ : fp++);
  for (const x of setE) if (!setO.has(x)) fn++;
}
const precision = tp / (tp + fp); const recall = tp / (tp + fn);
console.log({ precision, recall });
